CREATE TABLE wallets (id BIGINT PRIMARY KEY AUTO_INCREMENT, wallet_code VARCHAR(64) NOT NULL UNIQUE, public_key TEXT NOT NULL, network VARCHAR(32) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE participant_nodes (id BIGINT PRIMARY KEY AUTO_INCREMENT, node_code VARCHAR(64) NOT NULL UNIQUE, endpoint VARCHAR(255) NOT NULL, certificate_fingerprint VARCHAR(128) NOT NULL, status VARCHAR(16) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE key_epochs (id BIGINT PRIMARY KEY AUTO_INCREMENT, wallet_id BIGINT NOT NULL, epoch_no INT NOT NULL, public_key TEXT NOT NULL, status VARCHAR(16) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_key_epoch (wallet_id, epoch_no));
CREATE TABLE signing_sessions (id BIGINT PRIMARY KEY AUTO_INCREMENT, session_code VARCHAR(96) NOT NULL UNIQUE, wallet_id BIGINT NOT NULL, digest CHAR(64) NOT NULL, status VARCHAR(16) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE approvals (id BIGINT PRIMARY KEY AUTO_INCREMENT, session_id BIGINT NOT NULL, node_id BIGINT NOT NULL, decision VARCHAR(16) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_approval (session_id, node_id));
CREATE TABLE transactions (id BIGINT PRIMARY KEY AUTO_INCREMENT, session_id BIGINT NOT NULL, tx_hash VARCHAR(128), status VARCHAR(16) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, request_id VARCHAR(96) NOT NULL, actor VARCHAR(96) NOT NULL, action VARCHAR(96) NOT NULL, result VARCHAR(16) NOT NULL, detail TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
